// Sector colors
const sectorColors = {
    'Information Technology': '#4285f4',
    'Industry': '#ea4335',
    'Energy': '#fbbc04',
    'Financial': '#34a853',
    'ETF': '#9c27b0'
};

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return 'N/A';
    const num = parseFloat(value);
    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    return num.toFixed(2);
}

// Main visualization function
async function createVisualization() {
    // Load data
    const data = await d3.csv('data/stock-descriptions.csv');

    // Process data
    const stocks = data.map(d => ({
        ticker: d.ticker,
        name: d['full name'],
        sector: d.sector,
        marketCap: parseFloat(d.marketCap) || 0,
        country: d.country,
        website: d.website,
        isETF: d.sector === 'ETF'
    }));

    // Get unique sectors
    const sectors = [...new Set(stocks.map(d => d.sector))];

    // Create bubble chart
    createBubbleChart(stocks, sectors);

    // Create data table
    createDataTable(stocks);
}

function createBubbleChart(stocks, sectors) {
    const container = d3.select('#bubble-chart');
    const width = container.node().getBoundingClientRect().width;
    const height = 550;

    // Create SVG
    const svg = container.append('svg')
        .attr('width', width)
        .attr('height', height);

    // Create tooltip
    const tooltip = d3.select('body').append('div')
        .attr('class', 'tooltip');

    // Calculate bubble sizes
    const marketCaps = stocks.filter(d => d.marketCap > 0).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(marketCaps), d3.max(marketCaps)])
        .range([15, 50]);

    // ETF default radius
    const etfRadius = 20;

    // Assign radius to each stock
    stocks.forEach(d => {
        d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
    });

    // Sector positions for clustering
    const sectorPositions = {};
    const cols = 3;
    const sectorList = sectors.filter(s => s);
    sectorList.forEach((sector, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        sectorPositions[sector] = {
            x: (col + 1) * width / (cols + 1),
            y: (row + 1) * height / (Math.ceil(sectorList.length / cols) + 1)
        };
    });

    // Create force simulation
    const simulation = d3.forceSimulation(stocks)
        .force('x', d3.forceX(d => sectorPositions[d.sector]?.x || width / 2).strength(0.3))
        .force('y', d3.forceY(d => sectorPositions[d.sector]?.y || height / 2).strength(0.3))
        .force('collide', d3.forceCollide(d => d.radius + 2).strength(1))
        .force('center', d3.forceCenter(width / 2, height / 2).strength(0.05));

    // Create bubble groups
    const bubbleGroups = svg.selectAll('.bubble-group')
        .data(stocks)
        .enter()
        .append('g')
        .attr('class', 'bubble-group');

    // Add circles
    const bubbles = bubbleGroups.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector] || '#999')
        .attr('data-ticker', d => d.ticker)
        .on('mouseover', function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style('opacity', 1)
                    .html(`
                        <div class="ticker">${d.ticker}</div>
                        <div class="name">${d.name}</div>
                        <div class="sector">${d.sector}</div>
                    `);
            }
        })
        .on('mousemove', function(event) {
            tooltip
                .style('left', (event.pageX + 15) + 'px')
                .style('top', (event.pageY - 10) + 'px');
        })
        .on('mouseout', function() {
            tooltip.style('opacity', 0);
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Add labels
    const labels = bubbleGroups.append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius * 0.6, 12) + 'px');

    // Update positions on simulation tick
    simulation.on('tick', () => {
        bubbleGroups.attr('transform', d => {
            d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
            d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
            return `translate(${d.x}, ${d.y})`;
        });
    });

    // Create legend
    const legendContainer = d3.select('.chart-container').append('div')
        .attr('class', 'legend');

    sectors.filter(s => s).forEach(sector => {
        const item = legendContainer.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', sectorColors[sector]);

        item.append('span').text(sector);
    });
}

function createDataTable(stocks) {
    const container = d3.select('#data-table');

    const table = container.append('table');

    // Header
    const thead = table.append('thead');
    thead.append('tr')
        .selectAll('th')
        .data(['Ticker', 'Company Name', 'Sector', 'Market Cap'])
        .enter()
        .append('th')
        .text(d => d);

    // Body
    const tbody = table.append('tbody');

    const rows = tbody.selectAll('tr')
        .data(stocks)
        .enter()
        .append('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.name);
    rows.append('td').text(d => d.sector);
    rows.append('td')
        .attr('class', 'market-cap')
        .text(d => formatMarketCap(d.marketCap));
}

function selectStock(ticker) {
    // Clear previous selection
    d3.selectAll('.bubble').classed('selected', false);
    d3.selectAll('tbody tr').classed('selected', false);

    // Select bubble
    d3.select(`.bubble[data-ticker="${ticker}"]`).classed('selected', true);

    // Select and scroll to table row
    const row = d3.select(`tr[data-ticker="${ticker}"]`);
    row.classed('selected', true);

    // Scroll row into view
    const rowNode = row.node();
    if (rowNode) {
        rowNode.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}

// Initialize visualization when DOM is ready
document.addEventListener('DOMContentLoaded', createVisualization);
